"use client";

import { useState, useEffect, useMemo } from 'react';
import { useRouter } from 'next/navigation';
import { isStaticExport } from '@/lib/static-data';
import { FiLock, FiAlertTriangle, FiImage, FiSettings, FiUsers } from 'react-icons/fi';
import Link from 'next/link';
import { useSession } from 'next-auth/react';

export default function AdminPage() {
  const router = useRouter();
  const { data: session, status } = useSession();
  const [isStatic, setIsStatic] = useState(false);
  
  // Memoize the static check to prevent unnecessary recalculations
  const staticCheck = useMemo(() => {
    if (typeof window === 'undefined') return false;
    return isStaticExport();
  }, []);
  
  // Set static state only once on mount
  useEffect(() => {
    setIsStatic(staticCheck);
  }, [staticCheck]);
  
  // Handle authentication redirect
  useEffect(() => {
    if (status === 'unauthenticated') {
      router.replace('/admin/login');
    }
  }, [status, router]);
  
  // Show loading state while checking authentication
  if (status === 'loading') {
    return (
      <div className="flex items-center justify-center min-h-screen bg-zinc-900">
        <div className="p-4 text-center">
          <p className="text-zinc-300">Loading...</p>
        </div>
      </div>
    );
  }
  
  // In static export, show an access denied message
  if (isStatic) {
    return (
      <div className="flex items-center justify-center min-h-screen bg-zinc-900">
        <div className="w-full max-w-md p-8 bg-zinc-800 rounded-lg shadow-lg text-center">
          <FiLock className="mx-auto h-16 w-16 text-red-500 mb-4" />
          <h1 className="text-2xl font-bold text-white mb-2">Access Denied</h1>
          <div className="h-1 w-20 bg-red-500 mx-auto mb-6"></div>
          
          <p className="text-zinc-300 mb-6">
            Admin functionality is not available in the static site deployment.
          </p>
          
          <div className="bg-zinc-700 p-4 rounded-lg mb-6">
            <FiAlertTriangle className="inline-block mr-2 text-yellow-400" />
            <span className="text-zinc-300 text-sm">
              Administrative features are only available in the development environment.
            </span>
          </div>
          
          <Link 
            href="/"
            className="inline-flex items-center justify-center px-6 py-3 bg-zinc-700 hover:bg-zinc-600 text-white rounded-md transition-colors"
          >
            Return to Homepage
          </Link>
        </div>
      </div>
    );
  }
  
  // Show admin dashboard
  return (
    <div className="min-h-screen bg-zinc-900">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <h1 className="text-3xl font-bold text-white mb-8">Admin Dashboard</h1>
        
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {/* Photos Management Card */}
          <Link 
            href="/admin/photos"
            className="block p-6 bg-zinc-800 rounded-lg shadow-lg hover:bg-zinc-700 transition-colors"
          >
            <div className="flex items-center">
              <FiImage className="h-8 w-8 text-blue-500 mr-4" />
              <div>
                <h2 className="text-xl font-semibold text-white">Photos</h2>
                <p className="text-zinc-400">Manage your photo collection</p>
              </div>
            </div>
          </Link>
          
          {/* Settings Card */}
          <Link 
            href="/admin/settings"
            className="block p-6 bg-zinc-800 rounded-lg shadow-lg hover:bg-zinc-700 transition-colors"
          >
            <div className="flex items-center">
              <FiSettings className="h-8 w-8 text-green-500 mr-4" />
              <div>
                <h2 className="text-xl font-semibold text-white">Settings</h2>
                <p className="text-zinc-400">Configure site settings</p>
              </div>
            </div>
          </Link>
          
          {/* Users Card */}
          <Link 
            href="/admin/users"
            className="block p-6 bg-zinc-800 rounded-lg shadow-lg hover:bg-zinc-700 transition-colors"
          >
            <div className="flex items-center">
              <FiUsers className="h-8 w-8 text-purple-500 mr-4" />
              <div>
                <h2 className="text-xl font-semibold text-white">Users</h2>
                <p className="text-zinc-400">Manage user accounts</p>
              </div>
            </div>
          </Link>
        </div>
      </div>
    </div>
  );
}
